315	/**
316	 * Merge a freshly built graph into the nodes React Flow is currently showing,
317	 * keeping any position the user dragged a box to.
318	 *
319	 * A dragged box must survive a data refresh, but a re-LAYOUT must win. Those are
320	 * told apart by comparing the incoming layout position against the one this node
321	 * was last laid out at (`laidOutPosition`), not against where the node currently
322	 * sits: the current position is whatever the user dragged it to, so comparing
323	 * with it would treat every drag as a layout change and snap the box back.
324	 *
325	 * This matters because layout is async (ELK): boxes mount at the placeholder
326	 * graph's coordinates and the real ones arrive a render later. Preserving the
327	 * mounted positions unconditionally discarded every computed coordinate and
328	 * collapsed the map into a single column at the origin.
329	 *
330	 * Returns `current` unchanged when nothing rendered differs. That bail-out is
331	 * load bearing: the hook hands back a brand-new graph object every render (its
332	 * `rulesBySlug` comes from `useQueries`' combine), so a resync that always
333	 * produced a new array would be an infinite setState/render loop.
334	 *
335	 * Everything except position is compared, rather than a hand-listed subset —
336	 * a whitelist silently goes stale the moment a field is added to the node, and
337	 * has already caused renamed types and refreshed counts to keep displaying old
338	 * values.
339	 */
340	function mergeGraphIntoNodes(
341		current: SchemaFlowNode[],
342		next: SchemaFlowNode[],
343	): SchemaFlowNode[] {
344		const byId = new Map(current.map((node) => [node.id, node]));
345		let changed = current.length !== next.length;
346	
347		const merged = next.map((node, index) => {
348			const existing = byId.get(node.id);
349			if (!existing || current[index]?.id !== node.id) {
350				changed = true;
351				return node;
352			}
353	
354			// The layout moved this box: adopt the new coordinates verbatim. Returned
355			// before the rendered-state comparison below, which deliberately ignores
356			// position — going through it would compare equal and drop the move.
357			if (
358				existing.data.laidOutPosition?.x !== node.position.x ||
359				existing.data.laidOutPosition?.y !== node.position.y
360			) {
361				changed = true;
362				return node;
363			}
364	
365			// Keep where the user put it; take everything else from the rebuild.
366			const candidate: SchemaFlowNode = { ...node, position: existing.position };
367			if (renderedStateOf(existing) === renderedStateOf(candidate))
368				return existing;
369			changed = true;
370			return candidate;
371		});
372	
373		return changed ? merged : current;
374	}
375	
376	/** Everything about a node that affects what is drawn or where it links. */
377	function renderedStateOf(node: SchemaFlowNode): string {
378		const { position: _position, data, ...rest } = node;
379		// `laidOutPosition` is bookkeeping for the merge above, not something drawn.
380		const { laidOutPosition: _laidOut, ...renderedData } = data;
381		return JSON.stringify({ ...rest, data: renderedData });
382	}
