384	/**
385	 * Entities tab body when no type is scoped: an ERD of the workspace schema.
386	 *
387	 * Nodes are not directly editable. Clicking one opens its records, its pencil
388	 * opens the existing schema form, and the toolbar can add a declared
389	 * relationship. Boxes can be dragged to untangle a dense area, but positions
390	 * are not persisted — a reload returns to the computed layout.
391	 */
392	export function EntityTypeGraphView({ ownerSlug }: { ownerSlug: string }) {
393		const navigate = useNavigate();
394		const { orgContext } = useOrgContext();
395		// Schema authoring (`create`, `add_rule`) is in OWNER_ADMIN_ACTIONS, while
396		// reading the map is public-read. Offering these to a member would only get
397		// them an authorization failure after they filled the dialog in.
398		const { isAdmin } = useMembers(orgContext.organizationId);
399		const [addingRelationship, setAddingRelationship] = useState(false);
400		// Which cluster the side panel has focused, by cluster id. Clicking the same
401		// one again clears it, so the panel is a filter and not a mode you get stuck in.
402		const [focusedClusterId, setFocusedClusterId] = useState<string | null>(null);
403		// Boxes are headers only: the map is about how types relate, and full field
404		// lists on every box drown the edges out. Fields live in the type's editor.
405		const { graph, isLoading, isError, hasTypes } =
406			useEntitySchemaGraph(ownerSlug);
407	
408		// A cluster that disappears (its last rule was deleted) must not leave the
409		// canvas stuck dimmed, so resolve through the current graph rather than
410		// trusting the stored id.
411		const focusedCluster = useMemo(
412			() =>
413				graph.clusters.find((cluster) => cluster.id === focusedClusterId) ?? null,
414			[graph.clusters, focusedClusterId],
415		);
416	
417		const laidOutNodes = useMemo<SchemaFlowNode[]>(() => {
418			const focusedSlugs = focusedCluster ? new Set(focusedCluster.slugs) : null;
419			return graph.nodes.map((node) => ({
420				id: node.id,
421				type: "entityType" as const,
422				position: node.position,
423				width: node.width,
424				height: node.height,
425				// Spread so the literal satisfies React Flow's `Record<string, unknown>`
426				// data constraint without loosening `SchemaNodeData`.
427				data: {
428					...node.data,
429					isDimmed: focusedSlugs ? !focusedSlugs.has(node.id) : false,
430					// Where layout put this box, kept so a later rebuild can tell a
431					// re-layout apart from a box the user dragged.
432					laidOutPosition: node.position,
433				},
434			}));
435		}, [graph.nodes, focusedCluster]);
436	
437		// Dragging needs mutable node state, so React Flow owns positions once the
438		// canvas mounts. Nothing is persisted — a reload returns to the computed layout.
439		const [nodes, setNodes, onNodesChange] = useNodesState(laidOutNodes);
440	
441		// `useNodesState` seeds from its argument once, so a rebuilt graph — a
442		// renamed type, a new relationship, a refreshed entity count — has to be
443		// pushed in. See `mergeGraphIntoNodes` for why it must bail out when nothing
444		// rendered actually changed.
445		useEffect(() => {
446			setNodes((current) => mergeGraphIntoNodes(current, laidOutNodes));
447		}, [laidOutNodes, setNodes]);
448	
449		const edges = useMemo<Edge[]>(() => {
450			// Only highlight when a cluster is actually picked — with nothing selected
451			// every edge is equally relevant and dimming all of them helps no one.
452			const focus = focusedCluster ? new Set(focusedCluster.edgeIds) : undefined;
453	
454			return graph.edges.map((edge) => {
455				const dimmed = focus ? !focus.has(edge.id) : false;
456				// A collapsed edge says how many rules it stands for, so folding
457				// siblings never hides that there is more than one.
458				const label =
459					edge.data.ruleCount > 1
460						? `${edge.data.label} ×${edge.data.ruleCount}`
461						: edge.data.label;
462	
463				return {
464					id: edge.id,
465					source: edge.source,
466					target: edge.target,
467					sourceHandle: `${edge.id}-source`,
468					targetHandle: `${edge.id}-target`,
469					label,
470					// Match the layout's right-angled geometry instead of drawing
471					// overlapping bezier curves through the boxes.
472					type: "smoothstep",
473					pathOptions: { borderRadius: 12 },
474					className: cn(
475						"transition-opacity",
476						dimmed ? "opacity-15" : "text-muted-foreground",
477					),
478					// A symmetric relation is an unordered pair, so an arrowhead would
479					// assert a direction the data does not have.
480					markerEnd: edge.data.isSymmetric
481						? undefined
482						: { type: MarkerType.ArrowClosed, width: 14, height: 14 },
483				};
484			});
485		}, [graph.edges, focusedCluster]);
486	
487		// The panel lists types by slug; show the human name the boxes carry.
488		const labelBySlug = useMemo(
489			() => new Map(graph.nodes.map((node) => [node.data.slug, node.data.label])),
490			[graph.nodes],
491		);
492	
493		const endpointOptions = useMemo(
494			() =>
495				graph.nodes.map((node) => ({
496					slug: node.data.slug,
497					label: node.data.label,
498				})),
499			[graph.nodes],
500		);
501	
502		// No drag/click disambiguation is needed: the browser does not emit a click
503		// after a press that moved the pointer (verified in-browser — a drag fires
504		// pointerdown/pointerup and no click), so React Flow never turns a drag into
505		// an `onNodeClick`.
506		const handleNodeClick = useCallback(
507			(_: unknown, node: SchemaFlowNode) => {
508				void navigate(memoryBrowseTypeSearch(ownerSlug, node.data.slug));
509			},
510			[navigate, ownerSlug],
511		);
512	
513		if (isLoading) {
514			return (
515				<div
516					role="status"
517					aria-label="Loading workspace schema"
518					className="flex min-h-0 w-full flex-1 flex-col"
519				>
520					<Skeleton className="min-h-[420px] w-full flex-1 rounded-lg" />
521				</div>
522			);
523		}
524	
525		if (isError) {
526			return <TabErrorState label="workspace schema" />;
527		}
528	
529		if (!hasTypes) {
530			return (
531				<TabEmptyState
532					icon={Boxes}
533					title="No entity types yet"
534					description={
535						isAdmin
536							? "Entity types define the records Memory can track — companies, people, tickets, and anything else you model. Create a type to get started."
537							: "Entity types define the records Memory can track. An admin can add the first one."
538					}
539					actionLabel={isAdmin ? "Create entity type" : undefined}
540					onAction={
541						isAdmin
542							? () => void navigate(memoryCreateEntityTypeSearch(ownerSlug))
543							: undefined
544					}
545				/>
546			);
547		}
548	
549		return (
550			// Full width, not a centered reading column: a schema map is only as useful
551			// as the space it gets, and the diagram grows with the workspace.
552			<div className="flex min-h-0 w-full flex-1 flex-col gap-3">
553				<div className="flex flex-wrap items-center justify-between gap-3">
554					<p className="text-sm text-muted-foreground">
555						{graph.edges.length > 0
556							? "Your workspace schema. Click a type to browse its records, or edit one to change its fields and relationships."
557							: "Your workspace schema. Click a type to browse its records — relationships appear here once you add one to a type."}
558					</p>
559					{/* Reading the map is public-read, so the cluster index sits OUTSIDE
560					    the admin gate — only the authoring buttons are admin-only. */}
561					<div className="flex flex-wrap items-center gap-2">
562						<SchemaClusterMenu
563							clusters={graph.clusters}
564							islandSlugs={graph.islandSlugs}
565							labelBySlug={labelBySlug}
566							focusedClusterId={focusedClusterId}
567							onFocusCluster={setFocusedClusterId}
568						/>
569						{isAdmin ? (
570							<>
571								<Button
572									type="button"
573									variant="outline"
574									size="sm"
575									className="h-8 text-xs"
576									onClick={() => setAddingRelationship(true)}
577								>
578									<Spline className="mr-1.5 h-3.5 w-3.5" />
579									New relationship
580								</Button>
581								<Button
582									type="button"
583									variant="outline"
584									size="sm"
585									className="h-8 text-xs"
586									onClick={() =>
587										void navigate(memoryCreateEntityTypeSearch(ownerSlug))
588									}
589								>
590									Create entity type
591								</Button>
592							</>
593						) : null}
594					</div>
595				</div>
596	
597				{/* Canvas and index side by side: the panel is an index of the same
598				    graph, so it has to stay visible while the canvas is panned. */}
599				<div className="flex min-h-[420px] w-full min-w-0 flex-1 gap-4">
600					<div className="min-w-0 flex-1 overflow-hidden">
601						<ReactFlow
602							nodes={nodes}
603							edges={edges}
