9	/**
10	 * Pure model + layout for the entity-type ERD.
11	 *
12	 * Boxes are entity TYPES (not rows); edges are the DECLARED
13	 * `entity_relationship_type_rules` (source→target slug pairs), so the diagram
14	 * renders correctly even for an org with zero entity rows. Kept free of React
15	 * and of the data-fetching layer so the shape logic is unit-testable and the
16	 * rules source can change (per-slug fan-out today, a bulk endpoint later)
17	 * without touching the view.
18	 */
19	
20	export interface SchemaNodeData {
21		slug: string;
22		label: string;
23		/** Owner slug, so a node can link straight to its entity-type editor. */
24		ownerSlug: string;
25		icon?: string | null;
26		fieldCount: number;
27		/** Reserved `$…` type, rendered in a distinct color rather than hidden. */
28		isSystem: boolean;
29		entityCount?: number;
30		/** Edge-specific handles keep parallel relationships from overlapping. */
31		sourceHandleIds: string[];
32		targetHandleIds: string[];
33		/** Self-loop targets attach above the node so their paths remain visible. */
34		selfTargetHandleIds: string[];
35		/**
36		 * Set by the view when a cluster is focused and this type is not in it.
37		 * Layout does not compute it — it is view state, carried on the node because
38		 * React Flow only hands the renderer `data`.
39		 */
40		isDimmed?: boolean;
41		/**
42		 * Where layout last placed this node. Compared against the next layout's
43		 * position so a re-layout can be told apart from a user drag.
44		 */
45		laidOutPosition?: { x: number; y: number };
46	}
47	
48	interface SchemaEdgeData {
49		/** Relationship type slug (`works_at`), not the rule id. */
50		slug: string;
51		label: string;
52		/** Symmetric relations render without an arrowhead — the pair is unordered. */
53		isSymmetric: boolean;
54		/**
55		 * How many declared rules this one drawn edge stands for.
56		 *
57		 * Sibling rules of one relationship type on the same ordered pair are drawn
58		 * once with a count rather than as parallel paths: they carry identical text
59		 * and identical endpoints, so N paths added N crossings and zero information.
60		 */
61		ruleCount: number;
62	}
63	
64	export interface SchemaGraphNode {
65		id: string;
66		data: SchemaNodeData;
67		position: { x: number; y: number };
68		width: number;
69		height: number;
70	}
71	
72	export interface SchemaGraphEdge {
73		id: string;
74		source: string;
75		target: string;
76		data: SchemaEdgeData;
77	}
78	
79	export interface SchemaGraph {
80		nodes: SchemaGraphNode[];
81		edges: SchemaGraphEdge[];
82		/** Connected components, biggest first. Islands are excluded — see `schemaClusters`. */
83		clusters: SchemaCluster[];
84		/** Slugs of types no declared rule touches, in the order they are laid out. */
85		islandSlugs: string[];
86	}
87	
88	/** Rules keyed by the relationship-type slug they belong to. */
89	export type RulesBySlug = Record<string, RelationshipTypeRule[]>;
90	
91	const NODE_WIDTH = 220;
92	const HEADER_HEIGHT = 44;
93	
94	function compareSlugs(a: { slug: string }, b: { slug: string }): number {
95		return a.slug < b.slug ? -1 : a.slug > b.slug ? 1 : 0;
96	}
97	
98	/**
99	 * Keep active relationship types only. The accessible list is tenant-first and
100	 * may also contain a public type with the same slug; `list_rules` resolves that
101	 * slug tenant-first, so keep the first type to label its rules consistently.
102	 */
103	export function selectRelationshipTypesForGraph(
104		relationshipTypes: RelationshipType[],
105	): RelationshipType[] {
106		const seen = new Set<string>();
107		return relationshipTypes.filter((relationshipType) => {
108			if (relationshipType.status !== "active") return false;
109			if (seen.has(relationshipType.slug)) return false;
110			seen.add(relationshipType.slug);
111			return true;
112		});
113	}
114	
115	function schemaFieldCount(entityType: EntityType): number {
116		const schema = entityType.metadata_schema;
117		if (!schema || typeof schema !== "object") return 0;
118		const properties = (schema as Record<string, unknown>).properties;
119		if (!properties || typeof properties !== "object") return 0;
120		return Object.keys(properties).length;
121	}
122	
123	/**
124	 * Build the unpositioned graph. Only rules whose BOTH endpoints resolve to a
125	 * known type become edges — a rule naming a deleted type would otherwise
126	 * produce an edge to a node that does not exist.
127	 */
128	export function buildSchemaGraph(opts: {
129		entityTypes: EntityType[];
130		relationshipTypes: RelationshipType[];
131		rulesBySlug: RulesBySlug;
132		ownerSlug: string;
133	}): { nodes: Omit<SchemaGraphNode, "position">[]; edges: SchemaGraphEdge[] } {
134		const { entityTypes, relationshipTypes, rulesBySlug, ownerSlug } = opts;
135		const orderedEntityTypes = [...entityTypes].sort(compareSlugs);
136		const resolvedRelationshipTypes =
137			selectRelationshipTypesForGraph(relationshipTypes).sort(compareSlugs);
138	
139		const knownSlugs = new Set(orderedEntityTypes.map((et) => et.slug));
140		const edges: SchemaGraphEdge[] = [];
141		const sourceHandles = new Map<string, string[]>();
142		const targetHandles = new Map<string, string[]>();
143		const selfTargetHandles = new Map<string, string[]>();
144	
145		// Keyed by relationship type AND ordered pair: `contains` joining
146		// order→product and invoice→payment is two distinct edges, while two
147		// `works_at` rules on person→company is one edge drawn with a count.
148		const byPair = new Map<string, SchemaGraphEdge>();
149	
150		for (const rt of resolvedRelationshipTypes) {
151			const rules = [...(rulesBySlug[rt.slug] ?? [])].sort((a, b) => a.id - b.id);
152	
153			for (const rule of rules) {
154				const source = rule.source_entity_type_slug;
155				const target = rule.target_entity_type_slug;
156				if (!knownSlugs.has(source) || !knownSlugs.has(target)) continue;
157	
158				const pairKey = `${rt.slug}|${source}|${target}`;
159				const collapsed = byPair.get(pairKey);
160				if (collapsed) {
161					collapsed.data.ruleCount += 1;
162					continue;
163				}
164	
165				const edge: SchemaGraphEdge = {
166					// The first folded rule's id names the edge, so the id stays stable
167					// as long as that rule exists.
168					id: `rule-${rule.id}`,
169					source,
170					target,
171					data: {
172						slug: rt.slug,
173						label: rt.name || rt.slug,
174						isSymmetric: rt.is_symmetric,
175						ruleCount: 1,
176					},
177				};
178				byPair.set(pairKey, edge);
179				edges.push(edge);
180				sourceHandles.set(source, [
181					...(sourceHandles.get(source) ?? []),
182					`${edge.id}-source`,
183				]);
184				const targetHandleMap =
185					source === target ? selfTargetHandles : targetHandles;
186				targetHandleMap.set(target, [
187					...(targetHandleMap.get(target) ?? []),
188					`${edge.id}-target`,
189				]);
190			}
191		}
192	
193		const nodes = orderedEntityTypes.map((et) => {
194			return {
195				id: et.slug,
196				width: NODE_WIDTH,
197				// Header-only: the diagram is about relationships, and field lists
198				// compete with the edges for attention past a handful of types.
199				height: HEADER_HEIGHT,
200				data: {
201					slug: et.slug,
202					label: et.name || et.slug,
203					ownerSlug,
204					icon: et.icon,
205					fieldCount: schemaFieldCount(et),
206					isSystem: isSystemEntityType(et),
207					entityCount: et.entity_count,
208					sourceHandleIds: sourceHandles.get(et.slug) ?? [],
209					targetHandleIds: targetHandles.get(et.slug) ?? [],
210					selfTargetHandleIds: selfTargetHandles.get(et.slug) ?? [],
211				},
212			};
213		});
214	
215		return { nodes, edges };
216	}
217	
218	/**
219	 * A set of entity types reachable from one another through declared
220	 * relationships — one connected component of the schema graph.
221	 *
222	 * Surfaced so the view can list each connected group and focus it without
223	 * hiding the rest of the schema.
224	 */
225	export interface SchemaCluster {
226		/** Stable id: the alphabetically first member slug. */
227		id: string;
228		/** Member type slugs, sorted. */
229		slugs: string[];
230		/** Ids of edges whose endpoints are both in this cluster. */
231		edgeIds: string[];
232	}
233	
234	/**
235	 * Group connected types into clusters via union-find over the declared edges.
236	 *
237	 * Unconnected types are deliberately EXCLUDED — a component of one node is not
238	 * a cluster, it is an island, and listing nine single-node "clusters" buries the
239	 * one grouping that carries meaning. The view lists islands separately.
240	 */
241	export function schemaClusters(graph: {
242		nodes: { id: string }[];
243		edges: SchemaGraphEdge[];
244	}): SchemaCluster[] {
245		const parent = new Map<string, string>();
246		const find = (slug: string): string => {
247			const seen = parent.get(slug);
248			if (seen === undefined || seen === slug) return slug;
249			const root = find(seen);
250			parent.set(slug, root);
251			return root;
252		};
253		const union = (a: string, b: string) => {
254			const rootA = find(a);
255			const rootB = find(b);
256			if (rootA !== rootB) parent.set(rootA, rootB);
257		};
258	
259		for (const node of graph.nodes) parent.set(node.id, node.id);
260		// A self-loop connects a type to itself, which makes it a real (one-node)
261		// cluster rather than an island — it has a relationship to show.
262		for (const edge of graph.edges) union(edge.source, edge.target);
263	
264		const connected = new Set<string>();
265		for (const edge of graph.edges) {
266			connected.add(edge.source);
267			connected.add(edge.target);
268		}
269	
270		const byRoot = new Map<string, string[]>();
271		for (const node of graph.nodes) {
272			if (!connected.has(node.id)) continue;
273			const root = find(node.id);
274			byRoot.set(root, [...(byRoot.get(root) ?? []), node.id]);
275		}
276	
277		const clusters = [...byRoot.values()].map((slugs) => {
278			const members = [...slugs].sort();
279			const memberSet = new Set(members);
280			return {
281				id: members[0],
282				slugs: members,
283				edgeIds: graph.edges
284					.filter(
285						(edge) => memberSet.has(edge.source) && memberSet.has(edge.target),
286					)
287					.map((edge) => edge.id),
288			};
289		});
290	
291		// Biggest first — the largest component is the one worth reading first — then
292		// by id so the order never depends on map-iteration order.
293		return clusters.sort(
294			(a, b) =>
295				b.slugs.length - a.slugs.length ||
296				(a.id < b.id ? -1 : a.id > b.id ? 1 : 0),
297		);
298	}
299	
300	const MARGIN = 24;
301	/** Gap between the island column and the connected flow to its right. */
302	const ISLAND_COLUMN_GAP = 72;
303	/** Vertical gap between two stacked unconnected types. */
304	const ISLAND_ROW_GAP = 16;
305	
306	/**
307	 * ELK's layered layout, configured around orthogonal edges.
308	 *
309	 * dagre (layered/Sugiyama too) minimizes crossings between adjacent ranks but
310	 * does not account for edge lanes while positioning nodes. ELK does, so its
311	 * node coordinates leave more room for the smooth-step paths React Flow
312	 * renders between the matching, ordered handles.
313	 *
314	 * `layoutSchemaGraph` always feeds ELK slug-sorted nodes; repeated runs are
315	 * covered by the deterministic-layout test, so positions never need persisting.
316	 *
317	 * Async because ELK's API is promise-based. Only types a rule actually touches
318	 * are laid out; unconnected types have no edge to rank them and get their own
319	 * column at the top left.
320	 */
321	const elk = new ELK();
322	
323	/** Tuned for a schema map: wide ranks and room for separate edge paths. */
324	const ELK_OPTIONS: Record<string, string> = {
325		"elk.algorithm": "layered",
326		"elk.direction": "RIGHT",
327		"elk.edgeRouting": "ORTHOGONAL",
328		// These spacings affect the node coordinates ELK returns. React Flow renders
329		// the paths itself, using handles in the same edge order supplied here.
330		"elk.layered.spacing.edgeEdgeBetweenLayers": "12",
331		"elk.layered.spacing.edgeNodeBetweenLayers": "24",
332		"elk.layered.spacing.nodeNodeBetweenLayers": "120",
333		"elk.spacing.nodeNode": "32",
334		"elk.spacing.edgeEdge": "12",
335		"elk.spacing.edgeNode": "20",
336		// Keep a node's own edges in the order its handles are rendered, so an
337		// edge's line meets the handle it is anchored to instead of crossing to it.
338		"elk.layered.considerModelOrder.strategy": "NODES_AND_EDGES",
339		"elk.layered.crossingMinimization.semiInteractive": "true",
340	};
341	
342	async function layoutSchemaGraph(graph: {
343		nodes: Omit<SchemaGraphNode, "position">[];
344		edges: SchemaGraphEdge[];
345	}): Promise<SchemaGraph> {
346		const connected = new Set<string>();
347		for (const edge of graph.edges) {
348			connected.add(edge.source);
349			connected.add(edge.target);
350		}
351		const flowNodes = graph.nodes.filter((node) => connected.has(node.id));
352		const islandNodes = graph.nodes.filter((node) => !connected.has(node.id));
353	
354		// Islands take a column at the top LEFT, so the connected flow starts to the
355		// right of them instead of below them. Under the flow they sat off the bottom
356		// of the viewport on arrival; beside it they read as a legend of the types
357		// that simply have no relationships yet, visible without scrolling.
358		const islandColumnWidth = islandNodes.reduce(
359			(max, node) => Math.max(max, node.width),
360			0,
361		);
362		const flowOffsetX =
363			islandNodes.length > 0 ? MARGIN + islandColumnWidth + ISLAND_COLUMN_GAP : 0;
364	
365		let positioned: SchemaGraphNode[] = [];
366		if (flowNodes.length > 0) {
367			const laidOut = await elk.layout({
368				id: "root",
369				layoutOptions: ELK_OPTIONS,
370				children: flowNodes.map((node) => ({
371					id: node.id,
372					width: node.width,
373					height: node.height,
374				})),
375				// Self-references do not separate ranks and ELK rejects some of them
376				// outright, so they are excluded from layout. React Flow still receives
377				// and renders the edge.
378				edges: graph.edges
379					.filter((edge) => edge.source !== edge.target)
380					.map((edge) => ({
381						id: edge.id,
382						sources: [edge.source],
383						targets: [edge.target],
384					})),
385			});
386	
387			const byLaidOutId = new Map(
388				(laidOut.children ?? []).map((child) => [child.id, child]),
389			);
390			positioned = flowNodes.map((node) => {
391				const child = byLaidOutId.get(node.id);
392				// ELK reports top-left corners already, unlike dagre's centers.
393				return {
394					...node,
395					position: {
396						x: (child?.x ?? 0) + MARGIN + flowOffsetX,
397						y: (child?.y ?? 0) + MARGIN,
398					},
399				};
400			});
401		}
402	
403		// The column starts at the top margin rather than below the diagram — under
404		// the flow the islands landed off the bottom of the viewport on arrival.
405		let islandY = MARGIN;
406		const positionedIslands = islandNodes.map((node) => {
407			const position = { x: MARGIN, y: islandY };
408			islandY += node.height + ISLAND_ROW_GAP;
409			return { ...node, position };
410		});
411	
412		// Preserve the caller's node order so the output does not depend on which
413		// types happen to be connected.
414		const byId = new Map(
415			[...positioned, ...positionedIslands].map((node) => [node.id, node]),
416		);
417		const nodes = graph.nodes.map(
418			(node) =>
419				byId.get(node.id) ?? {
420					...node,
421					position: { x: MARGIN, y: MARGIN },
422				},
423		);
424	
425		return {
426			nodes,
427			edges: graph.edges,
428			clusters: schemaClusters(graph),
429			islandSlugs: islandNodes.map((node) => node.id),
430		};
431	}
432	
433	/** Build + lay out in one step. */
434	export function buildLaidOutSchemaGraph(opts: {
435		entityTypes: EntityType[];
436		relationshipTypes: RelationshipType[];
437		ownerSlug: string;
438		rulesBySlug: RulesBySlug;
439	}): Promise<SchemaGraph> {
440		return layoutSchemaGraph(buildSchemaGraph(opts));
441	}
