1	import { type UseQueryResult, useQueries } from "@tanstack/react-query";
2	import { useCallback, useEffect, useMemo, useState } from "react";
3	import { useOrgContext } from "@/hooks/use-org-context";
4	import {
5		type RelationshipTypeRule,
6		useEntityTypes,
7		useRelationshipTypeRules,
8		useRelationshipTypes,
9	} from "@/lib/api/entities";
10	import {
11		buildLaidOutSchemaGraph,
12		type RulesBySlug,
13		type SchemaGraph,
14		selectRelationshipTypesForGraph,
15	} from "./entity-schema-graph";
16	
17	/** Baseline state before the first ELK run and after a layout failure. */
18	const EMPTY_GRAPH: SchemaGraph = {
19		nodes: [],
20		edges: [],
21		clusters: [],
22		islandSlugs: [],
23	};
24	
25	/**
26	 * Data for the entity-type ERD.
27	 *
28	 * Unlike `useVisibleEntityTypes` (rail + scope bar) this KEEPS system types —
29	 * `$resource` is the ACL anchor for Slack channels and GitHub repos, so it is
30	 * one of the more informative nodes on the map. They are flagged, not dropped,
31	 * and the view colors them differently.
32	 *
33	 * Rules are fetched per relationship type (`list_rules` takes one slug), so this
34	 * is 2+N requests where N is the unique relationship-type count. A bulk rules
35	 * action can replace only this hook later;
36	 * `buildLaidOutSchemaGraph` is pure and does not care where rules came from.
37	 */
38	export function useEntitySchemaGraph(ownerSlug: string) {
39		const { orgContext, hasOrgContext } = useOrgContext();
40		const {
41			data: entityTypes = [],
42			isLoading: isTypesLoading,
43			isError: isTypesError,
44		} = useEntityTypes(orgContext);
45		const {
46			data: relationshipTypes = [],
47			isLoading: isRelTypesLoading,
48			isError: isRelTypesError,
49		} = useRelationshipTypes(orgContext);
50	
51		const scopedTypes = useMemo(
52			() =>
53				entityTypes.filter(
54					(et) => !et.organization_slug || et.organization_slug === ownerSlug,
55				),
56			[entityTypes, ownerSlug],
57		);
58	
59		const resolvedRelationshipTypes = useMemo(
60			() => selectRelationshipTypesForGraph(relationshipTypes),
61			[relationshipTypes],
62		);
63	
64		const combineRuleQueries = useCallback(
65			(results: UseQueryResult<RelationshipTypeRule[]>[]) => {
66				const bySlug: RulesBySlug = {};
67				resolvedRelationshipTypes.forEach((rt, idx) => {
68					const rules = results[idx]?.data;
69					if (rules?.length) bySlug[rt.slug] = rules;
70				});
71				return {
72					rulesBySlug: bySlug,
73					isRulesLoading: results.some((result) => result.isLoading),
74					isRulesError: results.some((result) => result.isError),
75				};
76			},
77			[resolvedRelationshipTypes],
78		);
79	
80		// One `list_rules` per relationship type, run in parallel. `useQueries` takes
81		// a dynamic-length list, so the query count can track the type count without
82		// violating the rules of hooks.
83		//
84		// `.queryOptions()` does not carry the hook's `enabled` predicate, so gate
85		// explicitly when there is no org context.
86		const { rulesBySlug, isRulesLoading, isRulesError } = useQueries({
87			queries: resolvedRelationshipTypes.map((rt) => ({
88				...useRelationshipTypeRules.queryOptions(rt.slug, orgContext),
89				enabled: hasOrgContext,
90			})),
91			// Fold the per-slug results in `combine` so the returned map is memoized on
92			// the query results themselves. The callback must also be stable: TanStack
93			// recomputes a combined result when the function identity changes.
94			// Only derive rule-query state here. Entity types are not inputs to
95			// `combine`, so graph construction belongs in the effect below.
96			combine: combineRuleQueries,
97		});
98	
99		const layoutInput = useMemo(
