/** One declared relationship type inside a bundled edge. */
export interface SchemaEdgeRelationship {
	/** Relationship type slug (`works_at`), not the rule id. */
	slug: string;
	label: string;
	/** Symmetric relations render without an arrowhead — the pair is unordered. */
	isSymmetric: boolean;
	/**
	 * How many declared rules this relationship contributes to the bundle.
	 *
	 * Sibling rules of one relationship type on the same ordered pair are counted
	 * rather than listed: they carry identical text and identical endpoints, so
	 * repeating the name N times adds nothing.
	 */
	ruleCount: number;
}

interface SchemaEdgeData {
	/**
	 * Every relationship this one drawn path stands for, in relationship-type
	 * order.
	 *
	 * ALL relationships between an ordered pair share a single path. Drawing one
	 * path per relationship type is what made a three-relationship pair
	 * unreadable: three lines between the same two boxes cannot be told apart
	 * without their labels, and three labels land on the same midpoint. The names
	 * are disclosed on hover instead, so the resting diagram shows the shape and
	 * the count without any text to collide.
	 */
	relationships: SchemaEdgeRelationship[];
	/**
	 * Whether an arrowhead is omitted. Only true when EVERY bundled relationship
	 * is symmetric — one directed member makes the drawn pair ordered.
	 */
	isSymmetric: boolean;
}

/**
 * Boxes size to their own name instead of sharing one fixed width.
 *
 * At a fixed 220px the name was the only flexible thing on a row it shared with
 * the field and record counts, so it was always the part that got an ellipsis —
 * "Company" rendered as "Comp…" while the counts beside it stayed whole. The
 * name identifies the box and the counts do not, so the counts moved to a second
 * line and the width now follows the longer of the two.
 */
const NODE_MIN_WIDTH = 200;
const NODE_MAX_WIDTH = 320;
/** Two lines: name, then `18 fields · 2,035 records`. */
const HEADER_HEIGHT = 56;

/**
 * Approximate advance width per character at each line's font size. Measuring
 * for real needs a DOM, which would make layout untestable and tie a pure module
 * to the browser; both lines still truncate, so an underestimate degrades to an
 * ellipsis rather than overflowing the box.
 */
const TITLE_CHAR_WIDTH = 7.4; // 13px / 600 weight
const META_CHAR_WIDTH = 5.9; // 11px / 400 weight
/** Padding, icon, gap, and the space the edit affordance needs on the name row. */
const TITLE_CHROME_WIDTH = 84;
/** Padding plus the second line's icon-width indent. */
const META_CHROME_WIDTH = 48;

function nodeWidth(label: string, metaLabel: string): number {
	return Math.round(
		Math.min(
			NODE_MAX_WIDTH,
			Math.max(
				NODE_MIN_WIDTH,
				TITLE_CHROME_WIDTH + label.length * TITLE_CHAR_WIDTH,
				META_CHROME_WIDTH + metaLabel.length * META_CHAR_WIDTH,
			),
		),
	);
}

/** The box's second line. Empty when there is nothing to count. */
function schemaMetaLabel(
	fieldCount: number,
	entityCount: number | undefined,
): string {
	const parts: string[] = [];
	if (fieldCount > 0) {
		parts.push(`${fieldCount} ${fieldCount === 1 ? "field" : "fields"}`);
	}
	if (typeof entityCount === "number") {
		parts.push(
			`${entityCount.toLocaleString()} ${entityCount === 1 ? "record" : "records"}`,
		);
	}
	return parts.join(" · ");
}

