// relationship entry rather than appended to it.
const byPairAndType = new Map<string, SchemaEdgeRelationship>();

for (const rt of resolvedRelationshipTypes) {
	const rules = [...(rulesBySlug[rt.slug] ?? [])].sort((a, b) => a.id - b.id);

	for (const rule of rules) {
		const source = rule.source_entity_type_slug;
		const target = rule.target_entity_type_slug;
		if (!knownSlugs.has(source) || !knownSlugs.has(target)) continue;

		const typeKey = `${rt.slug}|${source}|${target}`;
		const counted = byPairAndType.get(typeKey);
		if (counted) {
			counted.ruleCount += 1;
			continue;
		}

		const relationship: SchemaEdgeRelationship = {
			slug: rt.slug,
			label: rt.name || rt.slug,
			isSymmetric: rt.is_symmetric,
			ruleCount: 1,
		};
		byPairAndType.set(typeKey, relationship);

		const pairKey = `${source}|${target}`;
		const bundled = byPair.get(pairKey);
