import type {
	SchemaCluster,
	SchemaEdgeRelationship,
	SchemaNodeData,
} from "./entity-schema-graph";

const NODE_TYPES = { entityType: EntityTypeNode };

type SchemaFlowEdge = Edge<
	{
		relationships: SchemaEdgeRelationship[];
		/** The hovered node/edge touches this one, so its names are revealed. */
		isRevealed: boolean;
	} & Record<string, unknown>,
	"schema"
>;

/**
 * One path per ordered pair of types, drawn bare until it is asked about.
 *
 * Pinning a name to every edge midpoint is what made the map unreadable: labels
 * scale with edge count, land on the same midpoint whenever two types are joined
 * more than once, and no router places them out of each other's way. Every
 * serious schema tool (Azimutt, ChartDB, Supabase, drawDB) keeps edge text off
 * the resting canvas for exactly this reason.
 *
 * At rest, a path carries only a count, and only when it stands for more than
 * one relationship — that is the single fact a bare line hides. Hovering either
 * endpoint reveals the names, so the visible label count is bounded by one
 * node's degree instead of by the size of the whole graph.
 */
function SchemaEdge({
	sourceX,
	sourceY,
	sourcePosition,
	targetX,
	targetY,
	targetPosition,
	markerEnd,
	data,
	style,
}: EdgeProps<SchemaFlowEdge>) {
	const [path, labelX, labelY] = getSmoothStepPath({
		sourceX,
		sourceY,
		sourcePosition,
		targetX,
		targetY,
		targetPosition,
		borderRadius: 12,
	});

	const relationships = data?.relationships ?? [];
	const isRevealed = data?.isRevealed ?? false;
	const bundleCount = relationships.length > 1 ? relationships.length : null;

	return (
		<>
			<BaseEdge path={path} markerEnd={markerEnd} style={style} />
			{isRevealed || bundleCount ? (
				<EdgeLabelRenderer>
					{/* Non-interactive: the path underneath owns hover, and a label that
					    swallowed pointer events would flicker as the cursor crossed it. */}
					<div
						className="pointer-events-none absolute flex flex-col items-center gap-0.5"
						style={{
							transform: `translate(-50%, -50%) translate(${labelX}px, ${labelY}px)`,
							// Revealed names must sit over neighbouring paths and boxes,
							// or the thing just asked for renders underneath them.
							zIndex: isRevealed ? 10 : 1,
						}}
					>
						{isRevealed ? (
							relationships.map((relationship) => (
								<span
									key={relationship.slug}
									// A relationship name has no length limit, so cap the chip
									// and keep the full text in the tooltip rather than letting
									// one long name span the diagram.
									title={relationship.label}
									className={cn(
										"max-w-[180px] truncate rounded border border-border/70 bg-background px-1.5 py-0.5",
										"text-[11px] leading-tight text-foreground shadow-sm",
									)}
								>
									{relationship.ruleCount > 1
										? `${relationship.label} ×${relationship.ruleCount}`
										: relationship.label}
								</span>
							))
						) : (
							<span
								className={cn(
									"rounded-full border border-border/70 bg-background px-1.5",
									"text-[10px] leading-[16px] tabular-nums text-muted-foreground",
								)}
							>
								{bundleCount}
							</span>
						)}
					</div>
				</EdgeLabelRenderer>
			) : null}
		</>
	);
}

