	return graph.edges.map((edge) => {
		const dimmed = focus ? !focus.has(edge.id) : false;
		// Names are disclosed on demand rather than pinned to every path. A
		// dimmed edge is explicitly out of scope, so it stays quiet even under
		// the cursor. Cluster focus deliberately does NOT reveal: a cluster can
		// hold most of the schema, which would put every label back at once.
		const isRevealed =
			!dimmed &&
			(edge.id === hoveredEdgeId ||
				edge.source === hoveredNodeId ||
				edge.target === hoveredNodeId);

		return {
			id: edge.id,
			source: edge.source,
			target: edge.target,
			sourceHandle: `${edge.id}-source`,
			targetHandle: `${edge.id}-target`,
			// Right-angled geometry matching the layout, plus on-demand labels.
			type: "schema" as const,
			data: { relationships: edge.data.relationships, isRevealed },
			// Lift the revealed path above its neighbours along with its labels.
			zIndex: isRevealed ? 10 : 0,
			className: cn(
				"transition-opacity",
				dimmed
					? "opacity-15"
					: isRevealed
						? "text-foreground"
						: "text-muted-foreground",
			),
			// A symmetric relation is an unordered pair, so an arrowhead would
			// assert a direction the data does not have.
			markerEnd: edge.data.isSymmetric
				? undefined
				: { type: MarkerType.ArrowClosed, width: 14, height: 14 },
		};
	});
}, [graph.edges, focusedCluster, hoveredNodeId, hoveredEdgeId]);

