import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
	Select,
	SelectContent,
	SelectItem,
	SelectSeparator,
	SelectTrigger,
	SelectValue,
} from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { useOrgContext } from "@/hooks/use-org-context";
import {
	type RelationshipType,
	useAddRelationshipTypeRule,
	useCreateRelationshipType,
	useRelationshipTypes,
} from "@/lib/api/entities";

/** Sentinel for the "define a new relationship type" option in the picker. */
const NEW_TYPE = "__new__";

function slugify(name: string): string {
	return name
		.toLowerCase()
		.replace(/[^a-z0-9]+/g, "_")
		.replace(/^_+|_+$/g, "");
}

/**
 * Draw a new edge on the schema map, from inside the map's own side panel.
 *
 * Relationship types are workspace-level (`entity_relationship_types` keys on
 * the organization, not on an entity type), so this belongs to the canvas
 * rather than to any one box. Creating one is two steps — the type, then a
 * rule pairing two entity types — and a type with no rule draws nothing, so
 * both happen together here.
 *
 * This used to be a modal. The two things being picked are `From` and `To`,
 * which are boxes drawn on the canvas — and the modal covered the canvas while
 * you chose them. Rendered beside the map instead, the endpoints stay visible,
 * and the new edge appears the moment it is saved. It also keeps dialogs
 * reserved for OAuth and the command palette, per the design rules.
 */
export function NewRelationshipForm({
	entityTypes,
	onDone,
}: {
	/** Selectable endpoints — the same types the map draws. */
	entityTypes: { slug: string; label: string }[];
	/** Saved or cancelled; the panel collapses the form either way. */
	onDone: () => void;
}) {
	const { orgContext } = useOrgContext();
	const { data: relationshipTypes = [] } = useRelationshipTypes(orgContext);
	const createType = useCreateRelationshipType();
	const addRule = useAddRelationshipTypeRule();

	const [relTypeSlug, setRelTypeSlug] = useState("");
	const [name, setName] = useState("");
	const [isSymmetric, setIsSymmetric] = useState(false);
	const [source, setSource] = useState("");
	const [target, setTarget] = useState("");
	const [error, setError] = useState<string | null>(null);

	const isNewType = relTypeSlug === NEW_TYPE;
	// Public-catalog relationship types are readable but cannot be mutated by
	// this organization, so offering them here would make add_rule fail with 404.
	const activeTypes = relationshipTypes.filter(
		(rt: RelationshipType) =>
			rt.status === "active" &&
			(!rt.organization_slug || rt.organization_slug === orgContext?.slug),
	);
	const isSaving = createType.isPending || addRule.isPending;

	const handleSave = async () => {
		setError(null);
		if (!relTypeSlug) return setError("Pick a relationship");
		if (!source || !target) return setError("Pick both ends");

		try {
			let slug = relTypeSlug;
			if (isNewType) {
				const trimmed = name.trim();
				if (!trimmed) return setError("Name the relationship");
				const generated = slugify(trimmed);
				if (!generated) return setError("Name must contain a letter or number");
				const created = await createType.mutateAsync({
					slug: generated,
					name: trimmed,
					is_symmetric: isSymmetric,
				});
				slug = created.relationship_type.slug;
				// If add_rule fails after create succeeds, keep the created type
				// selected so Retry does not attempt the same create and hit 409.
				setRelTypeSlug(slug);
			}

			await addRule.mutateAsync({
				slug,
				source_entity_type_slug: source,
				target_entity_type_slug: target,
			});
			onDone();
		} catch (e) {
			setError(e instanceof Error ? e.message : "Could not save");
		}
	};

	return (
		<div className="flex flex-col gap-3 rounded-md border border-border bg-muted/30 p-3">
			<p className="text-[11px] leading-relaxed text-muted-foreground">
				Relationships are defined once for the workspace, then paired with the
				types they connect.
			</p>

			<div className="space-y-1.5">
				<Label htmlFor="rel-type" className="text-xs">
					Relationship
				</Label>
				<Select value={relTypeSlug} onValueChange={setRelTypeSlug}>
					<SelectTrigger id="rel-type" className="h-8 text-xs">
						<SelectValue placeholder="Pick or define one" />
					</SelectTrigger>
					<SelectContent>
						{activeTypes.map((rt: RelationshipType) => (
							<SelectItem key={rt.slug} value={rt.slug}>
								{rt.name || rt.slug}
							</SelectItem>
						))}
						{activeTypes.length > 0 ? <SelectSeparator /> : null}
						<SelectItem value={NEW_TYPE}>Define a new one…</SelectItem>
					</SelectContent>
				</Select>
			</div>

			{isNewType ? (
				<>
					<div className="space-y-1.5">
						<Label htmlFor="rel-name" className="text-xs">
							Name
						</Label>
						<Input
							id="rel-name"
							value={name}
							onChange={(e) => setName(e.target.value)}
							placeholder="works at"
							className="h-8 text-xs"
						/>
						{name.trim() ? (
							<p className="text-[11px] text-muted-foreground">
								Slug: <code>{slugify(name) || "—"}</code>
							</p>
						) : null}
					</div>
					<div className="flex items-start justify-between gap-2">
						<Label htmlFor="rel-symmetric" className="text-xs font-normal">
							Symmetric
							<span className="mt-0.5 block text-[11px] text-muted-foreground">
								Both ends mean the same thing, like “connected with”.
							</span>
						</Label>
						<Switch
							id="rel-symmetric"
							checked={isSymmetric}
							onCheckedChange={setIsSymmetric}
						/>
					</div>
				</>
			) : null}

			{/* Stacked, not the dialog's two columns: at panel width a pair of
			    side-by-side selects truncates the very type names being chosen. */}
			<div className="space-y-1.5">
				<Label htmlFor="rel-source" className="text-xs">
					From
				</Label>
				<Select value={source} onValueChange={setSource}>
					<SelectTrigger id="rel-source" className="h-8 text-xs">
						<SelectValue placeholder="Type" />
					</SelectTrigger>
					<SelectContent>
						{entityTypes.map((et) => (
							<SelectItem key={et.slug} value={et.slug}>
								{et.label}
							</SelectItem>
						))}
					</SelectContent>
				</Select>
			</div>
			<div className="space-y-1.5">
				<Label htmlFor="rel-target" className="text-xs">
					To
				</Label>
				<Select value={target} onValueChange={setTarget}>
					<SelectTrigger id="rel-target" className="h-8 text-xs">
						<SelectValue placeholder="Type" />
					</SelectTrigger>
					<SelectContent>
						{entityTypes.map((et) => (
							<SelectItem key={et.slug} value={et.slug}>
								{et.label}
							</SelectItem>
						))}
					</SelectContent>
				</Select>
			</div>

			{error ? <p className="text-xs text-destructive">{error}</p> : null}

			<div className="flex justify-end gap-2">
				<Button
					type="button"
					variant="outline"
					size="sm"
					className="h-7 text-xs"
					onClick={onDone}
					disabled={isSaving}
				>
					Cancel
				</Button>
				<Button
					type="button"
					size="sm"
					className="h-7 text-xs"
					onClick={handleSave}
					disabled={isSaving}
				>
					{isSaving ? "Saving…" : "Add relationship"}
				</Button>
			</div>
		</div>
	);
}

