import { TabLoadingState } from "@/components/entity-tabs/tab-states";
import { EntityTypePage } from "@/components/settings/entity-types/entity-type-page";
import { useOrgContext } from "@/hooks/use-org-context";
import { useEntityTypesAdmin } from "@/lib/api";
import { isSystemEntityType } from "@/lib/reserved";

/**
 * The entity-type editor, hosted inside the schema map's side panel.
 *
 * Creating and editing a type used to take over the whole pane (create) or
 * navigate away to `/$owner/entity-types/$slug` (edit) — both of which hid the
 * map you were editing. Beside the canvas, a rename or a new field shows up on
 * the box as soon as it saves, and the surrounding schema stays visible while
 * you decide what the type should look like.
 *
 * `EntityTypePage` is reused verbatim rather than reimplemented narrow: it owns
 * create, edit, the audit trail and the delete zone, and a second copy of that
 * would drift. The routed page stays — the entity-type rail links straight to
 * it, and this panel is not reachable from there.
 */
export function SchemaTypeEditorPanel({
	slug,
	onClose,
}: {
	/** `null` opens the editor in create mode. */
	slug: string | null;
	onClose: () => void;
}) {
	const { orgContext } = useOrgContext();
	const { data: entityTypes = [], isLoading } = useEntityTypesAdmin(orgContext);

	if (slug === null) {
		return (
			<EntityTypePage
				entityType={null}
				orgContext={orgContext}
				onClose={onClose}
			/>
		);
	}

	if (isLoading) {
		return <TabLoadingState label="entity type" variant="panel" />;
	}

	const entityType = entityTypes.find((et) => et.slug === slug) ?? null;
	if (!entityType) {
		return (
			<p className="text-sm text-muted-foreground">Entity type not found.</p>
		);
	}

	return (
		<EntityTypePage
			entityType={entityType}
			orgContext={orgContext}
			// `$…` system types can be edited lightly but never deleted.
			hideDelete={isSystemEntityType(entityType)}
			onClose={onClose}
		/>
	);
}

