const EDGE_TYPES = { schema: SchemaEdge };

/**
 * What the side panel is showing.
 *
 * `index` is the resting state — the map's table of contents. The others are
 * authoring surfaces that take the panel over, so schema editing happens beside
 * the diagram it changes rather than on a page that hides it.
 */
type PanelMode =
	| { kind: "index" }
	| { kind: "new-relationship" }
	/** `slug: null` is create mode. */
	| { kind: "edit-type"; slug: string | null };

/**
 * Lets a canvas node reach the panel. Passed by context rather than on node
 * `data`: React Flow's data is compared by value to decide when a box needs
 * redrawing (see `renderedStateOf`), and a callback has no business in that.
 */
const SchemaCanvasActionsContext = createContext<{
	onEditType: (slug: string) => void;
} | null>(null);

interface SchemaPanelProps {
	clusters: SchemaCluster[];
	islandSlugs: string[];
	labelBySlug: Map<string, string>;
	focusedClusterId: string | null;
	onFocusCluster: (clusterId: string | null) => void;
	/** Endpoints the relationship form can pair. */
	endpointOptions: { slug: string; label: string }[];
	/** Schema authoring is admin-only; reading the index is not. */
	canAuthor: boolean;
	mode: PanelMode;
	onModeChange: (mode: PanelMode) => void;
}

/**
 * The panel body, without a container. Rendered twice — as the wide-viewport
 * sidebar and inside the narrow-viewport popover — so the two presentations
 * cannot drift apart.
 */
function SchemaPanelContent({
	clusters,
	islandSlugs,
	labelBySlug,
	focusedClusterId,
	onFocusCluster,
	endpointOptions,
	canAuthor,
	mode,
	onModeChange,
}: SchemaPanelProps) {
	const labelOf = (slug: string) => labelBySlug.get(slug) ?? slug;
	const closePanelMode = () => onModeChange({ kind: "index" });

	// The type editor is the whole panel while it is open: it is a nine-group
	// form, and leaving the cluster index below it would bury the Save button
	// under a list nobody is reading mid-edit.
	if (canAuthor && mode.kind === "edit-type") {
		return <SchemaTypeEditorPanel slug={mode.slug} onClose={closePanelMode} />;
	}

	return (
		<>
			{canAuthor ? (
				<div className="flex flex-col gap-2">
					{mode.kind === "new-relationship" ? (
						<NewRelationshipForm
							entityTypes={endpointOptions}
							onDone={closePanelMode}
						/>
					) : (
						<Button
							type="button"
							variant="outline"
							size="sm"
							className="h-8 justify-start text-xs"
							onClick={() => onModeChange({ kind: "new-relationship" })}
						>
							<Spline className="mr-1.5 h-3.5 w-3.5" />
							New relationship
						</Button>
					)}
				</div>
			) : null}

