3	/**
4	 * Subscribe to a container element's width via ResizeObserver and return true
5	 * when the measured width is at or below `max`. Used by ResponsiveAppShell so
6	 * the narrow chrome decision tracks the container (e.g. Chrome side panel
7	 * iframe), not just the window — `window.matchMedia` mis-reports inside
8	 * iframes.
9	 *
10	 * Initial value stays `false` on first render and is corrected on the first
11	 * post-mount measurement. This avoids hydration mismatches if the app is ever
12	 * server-rendered (window-based seeding would diverge from SSR's `false`),
13	 * and matches the convention of `useSyncExternalStore`-style hooks.
14	 */
15	export function useContainerQuery(
16	  ref: RefObject<HTMLElement | null>,
17	  max: number
18	): boolean {
19	  const [isNarrow, setIsNarrow] = useState<boolean>(false);
20	
21	  useEffect(() => {
22	    const node = ref.current;
23	    if (!node) return;
24	    // Initial measurement — covers the first paint before any resize event.
25	    setIsNarrow(node.clientWidth <= max);
26	
27	    if (typeof ResizeObserver === 'undefined') return;
28	    const observer = new ResizeObserver((entries) => {
29	      const entry = entries[0];
30	      if (!entry) return;
31	      setIsNarrow(entry.contentRect.width <= max);
32	    });
33	
34	    observer.observe(node);
35	    return () => observer.disconnect();
36	  }, [ref, max]);
37	
38	  return isNarrow;
