import { getStored, removeStored, setStored } from "@/lib/storage";

/**
 * Width rules for the schema map's side panel, kept out of the view so the
 * clamping and persistence can be tested without a DOM.
 *
 * The panel sizes itself by mode — an index needs far less room than the type
 * editor — and a drag overrides that for good. Two defaults rather than one
 * because the un-dragged case should already be right: an editor that opens at
 * index width would make dragging mandatory instead of optional.
 */
export const PANEL_INDEX_WIDTH = 288;
export const PANEL_EDITOR_WIDTH = 440;

/** Below this the panel's own labels and selects start truncating. */
export const PANEL_MIN_WIDTH = 240;
/** Past this the panel stops being a sidebar and the map stops being the point. */
export const PANEL_MAX_WIDTH = 720;
/** A drag may never squeeze the canvas below this — the map stays a map. */
export const CANVAS_MIN_WIDTH = 320;

const STORAGE_KEY = "lobu.schema-panel-width";

/**
 * Fit `width` into what the panel is allowed to take, given the space the
 * canvas + panel row actually has.
 *
 * The canvas reservation is what stops a drag from collapsing the diagram, but
 * it cannot win outright: on a narrow container `available - CANVAS_MIN_WIDTH`
 * can fall below the panel's own minimum, and honouring it there would return a
 * width too small for the panel to render. The panel minimum wins that tie.
 */
export function clampPanelWidth(width: number, available: number): number {
	if (!Number.isFinite(width)) return PANEL_INDEX_WIDTH;
	const ceiling = Math.max(
		PANEL_MIN_WIDTH,
		Math.min(PANEL_MAX_WIDTH, available - CANVAS_MIN_WIDTH),
	);
	return Math.round(Math.min(ceiling, Math.max(PANEL_MIN_WIDTH, width)));
}

/**
 * The persisted width, or `null` when the reader should fall back to the
 * mode default.
 *
 * Values outside the allowed range are treated as absent rather than clamped
 * in: they mean the stored value predates a bounds change or was hand-edited,
 * and the mode default is a better answer than an arbitrary edge.
 */
export function readStoredPanelWidth(): number | null {
	const raw = getStored(STORAGE_KEY);
	if (raw === null) return null;
	const parsed = Number.parseInt(raw, 10);
	if (!Number.isFinite(parsed)) return null;
	if (parsed < PANEL_MIN_WIDTH || parsed > PANEL_MAX_WIDTH) return null;
	return parsed;
}

export function storePanelWidth(width: number): void {
	setStored(STORAGE_KEY, String(Math.round(width)));
}

/** Drop the override so the panel goes back to sizing itself by mode. */
export function clearStoredPanelWidth(): void {
	removeStored(STORAGE_KEY);
}

