function SchemaPanel(props: SchemaPanelProps & { width: number }) {
	const isEditing = props.canAuthor && props.mode.kind === "edit-type";

	return (
		<aside
			// Driven by a variable rather than a width class so the drag handle can
			// change it per-frame without re-deriving Tailwind classes, and so the
			// `lg:` prefix still gates it — below that breakpoint the panel is either
			// absent or full-bleed, and a pixel width would fight both.
			style={{ "--schema-panel-width": `${props.width}px` } as CSSProperties}
			className={cn(
				"shrink-0 flex-col gap-4 overflow-y-auto lg:flex lg:w-[var(--schema-panel-width)]",
				// Below `lg` the panel is normally absent (the popover carries the
				// index), but the editor still has to land somewhere: without this it
				// set a mode that nothing rendered, and "Create entity type" looked
				// broken on a phone. There is no room for canvas AND editor at that
				// width, so the editor takes the screen — the same trade the routed
				// page used to make, minus the navigation.
				isEditing ? "flex w-full" : "hidden",
			)}
		>
			<SchemaPanelContent {...props} />
		</aside>
	);
}

/**
 * The divider between canvas and panel, draggable to retune the split.
 *
 * The panel already picks a sensible width per mode, so this is for the cases a
 * default cannot know: a type carrying far more fields than most, a workspace
 * whose schema deserves the whole screen, a display much wider than the one the
 * defaults were measured on.
 *
 * It is the border as well as the grip. A separate hairline plus a drag strip
 * would put two vertical lines in the same gap, and the affordance belongs on
 * the thing that already reads as the seam.
 *
 * Hand-rolled rather than pulled from a panel library: this is one axis, one
 * divider, and a dependency would bring a layout engine to a problem that is
 * `startWidth - dx` clamped.
 */
function SchemaPanelResizeHandle({
	width,
	onResize,
	onCommit,
	onReset,
}: {
	width: number;
	/** Fires per pointer frame — deliberately not persisted until release. */
	onResize: (width: number) => void;
	onCommit: (width: number) => void;
	/** Double-click, or Home: hand sizing back to the mode default. */
	onReset: () => void;
}) {
	const [isDragging, setIsDragging] = useState(false);
	// The row that holds canvas + handle + panel; its width is the budget a drag
	// divides, and it changes with the window, so it is read per gesture.
	const rowWidthRef = useRef(0);

	const handlePointerDown = (event: ReactPointerEvent<HTMLDivElement>) => {
		// Left button only: a right-drag would start a resize that no `pointerup`
		// of the context menu ever ends.
		if (event.button !== 0) return;
		const handle = event.currentTarget;
		const row = handle.parentElement;
		if (!row) return;

		event.preventDefault();
		rowWidthRef.current = row.clientWidth;
		const startX = event.clientX;
		const startWidth = width;
		setIsDragging(true);
		// Capture keeps the gesture on the handle even when the pointer crosses
		// onto the canvas, which would otherwise start a React Flow pan.
		handle.setPointerCapture(event.pointerId);

		// Panel is on the right, so leftward travel (negative dx) widens it.
		const widthAt = (clientX: number) =>
			clampPanelWidth(startWidth - (clientX - startX), rowWidthRef.current);

		const onPointerMove = (moveEvent: PointerEvent) => {
			onResize(widthAt(moveEvent.clientX));
		};
		const onPointerUp = (upEvent: PointerEvent) => {
			handle.removeEventListener("pointermove", onPointerMove);
			handle.removeEventListener("pointerup", onPointerUp);
			handle.removeEventListener("pointercancel", onPointerUp);
			setIsDragging(false);
			// `pointercancel` carries no meaningful position — settle on the last
			// good width rather than snapping to wherever the cancel reports.
			onCommit(
				upEvent.type === "pointercancel" ? width : widthAt(upEvent.clientX),
			);
		};

		handle.addEventListener("pointermove", onPointerMove);
		handle.addEventListener("pointerup", onPointerUp);
		handle.addEventListener("pointercancel", onPointerUp);
	};

	const handleKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
		const row = event.currentTarget.parentElement;
		const available = row?.clientWidth ?? 0;
		const nudge = (delta: number) => {
			event.preventDefault();
			onCommit(clampPanelWidth(width + delta, available));
		};
		// Keyboard-reachable because a pointer-only divider is unusable to anyone
		// driving this from the keyboard, and the panel hosts the type editor.
		if (event.key === "ArrowLeft") nudge(16);
		else if (event.key === "ArrowRight") nudge(-16);
		else if (event.key === "Home") {
			event.preventDefault();
			onReset();
		}
	};

	return (
		// biome-ignore lint/a11y/useFocusableInteractive: `separator` takes tabIndex
		<div
			role="separator"
			aria-orientation="vertical"
			aria-label="Resize schema panel"
			aria-valuenow={width}
			aria-valuemin={PANEL_MIN_WIDTH}
			aria-valuemax={PANEL_MAX_WIDTH}
			tabIndex={0}
			onPointerDown={handlePointerDown}
			onKeyDown={handleKeyDown}
			onDoubleClick={onReset}
			className={cn(
				// `touch-none` stops a touch drag from scrolling the page instead.
				"group hidden shrink-0 cursor-col-resize touch-none items-stretch justify-center px-1.5 outline-none lg:flex",
				isDragging && "cursor-col-resize",
			)}
		>
			{/* Hairline at rest, thicker and accented while grabbed, so the seam
			    stays quiet until you go looking for it. */}
			<div
				className={cn(
					"w-px rounded-full bg-border transition-[background-color,width] group-hover:w-0.5 group-hover:bg-primary/60 group-focus-visible:w-0.5 group-focus-visible:bg-primary",
					isDragging && "w-0.5 bg-primary",
				)}
			/>
		</div>
	);
}

const isTypeEditorOpen = isAdmin && panelMode.kind === "edit-type";

// `null` means "size by mode"; a number is the width the user dragged to.
// Once set it wins over the mode default in both directions — having a drag
// silently revert when the editor opens would make the handle feel broken.
const [draggedWidth, setDraggedWidth] = useState<number | null>(() =>
	readStoredPanelWidth(),
);
const panelWidth =
	draggedWidth ??
	(isTypeEditorOpen ? PANEL_EDITOR_WIDTH : PANEL_INDEX_WIDTH);
const commitPanelWidth = useCallback((next: number) => {
	setDraggedWidth(next);
	storePanelWidth(next);
}, []);
const resetPanelWidth = useCallback(() => {
	setDraggedWidth(null);
	clearStoredPanelWidth();
}, []);

{/* Hidden with the panel below `lg`: there the panel is either absent
    or full-bleed, so there is no split left to tune. */}
<SchemaPanelResizeHandle
	width={panelWidth}
	onResize={setDraggedWidth}
	onCommit={commitPanelWidth}
	onReset={resetPanelWidth}
/>

<SchemaPanel
	width={panelWidth}
	clusters={graph.clusters}

{/* `gap-2` not `gap-4`: the resize handle sits in this gap and carries its
    own padding, and the two together should read as one seam. */}
<div className="flex min-h-[420px] w-full min-w-0 flex-1 gap-2">

