import { beforeEach, describe, expect, it } from "vitest";
import {
	CANVAS_MIN_WIDTH,
	clampPanelWidth,
	clearStoredPanelWidth,
	PANEL_MAX_WIDTH,
	PANEL_MIN_WIDTH,
	readStoredPanelWidth,
	storePanelWidth,
} from "./schema-panel-resize";

const WIDE = 1600;

describe("clampPanelWidth", () => {
	it("keeps a width that is already in range", () => {
		expect(clampPanelWidth(420, WIDE)).toBe(420);
	});

	it("refuses to shrink the panel past its own minimum", () => {
		expect(clampPanelWidth(40, WIDE)).toBe(PANEL_MIN_WIDTH);
	});

	it("refuses to grow the panel past its maximum", () => {
		expect(clampPanelWidth(5000, WIDE)).toBe(PANEL_MAX_WIDTH);
	});

	it("leaves the canvas its minimum width on a narrow row", () => {
		// 900 - 320 = 580, which bites before the 720 maximum does.
		expect(clampPanelWidth(PANEL_MAX_WIDTH, 900)).toBe(900 - CANVAS_MIN_WIDTH);
	});

	it("keeps the panel usable when the row cannot satisfy both minimums", () => {
		// 400 - 320 = 80: honouring the canvas here would return a width the panel
		// cannot render in, so the panel minimum has to win.
		expect(clampPanelWidth(300, 400)).toBe(PANEL_MIN_WIDTH);
	});

	it("rounds to whole pixels so the style value stays stable", () => {
		expect(clampPanelWidth(380.6, WIDE)).toBe(381);
	});

	it("falls back to a sane width when handed a non-number", () => {
		expect(clampPanelWidth(Number.NaN, WIDE)).toBe(288);
	});
});

describe("panel width persistence", () => {
	beforeEach(() => {
		clearStoredPanelWidth();
	});

	it("reads back what it stored", () => {
		storePanelWidth(512);
		expect(readStoredPanelWidth()).toBe(512);
	});

	it("reports no override before anything is stored", () => {
		expect(readStoredPanelWidth()).toBeNull();
	});

	it("forgets the override once cleared", () => {
		storePanelWidth(512);
		clearStoredPanelWidth();
		expect(readStoredPanelWidth()).toBeNull();
	});

	it("ignores a stored width outside the allowed range", () => {
		// A value left over from different bounds, or hand-edited: the mode
		// default is a better answer than clamping to an arbitrary edge.
		window.localStorage.setItem("lobu.schema-panel-width", "5000");
		expect(readStoredPanelWidth()).toBeNull();
	});

	it("ignores a stored value that is not a number", () => {
		window.localStorage.setItem("lobu.schema-panel-width", "wide");
		expect(readStoredPanelWidth()).toBeNull();
	});
});

