/**
 * jsdom 29 delegates Web Storage to Node's implementation, which is inert
 * unless the runner is started with `--localstorage-file` — so `localStorage`
 * is absent here, and `@/lib/storage` would swallow every write into its
 * private-mode fallback. This is the same Storage shape a browser hands the
 * app, restored afterwards so the stub cannot leak into another suite.
 */
function installStorageStub(): () => void {
	const entries = new Map<string, string>();
	const descriptor = Object.getOwnPropertyDescriptor(window, "localStorage");
	Object.defineProperty(window, "localStorage", {
		configurable: true,
		value: {
			getItem: (key: string) => entries.get(key) ?? null,
			setItem: (key: string, value: string) => entries.set(key, value),
			removeItem: (key: string) => entries.delete(key),
			clear: () => entries.clear(),
		},
	});
	return () => {
		if (descriptor) Object.defineProperty(window, "localStorage", descriptor);
		else Reflect.deleteProperty(window, "localStorage");
	};
}

