describe("EntityTypeGraphView panel resizing", () => {
	/**
	 * jsdom performs no layout, so every element measures 0 and the clamp would
	 * pin the panel to its minimum on every gesture. Give the row the width a
	 * real viewport would report.
	 */
	function grabHandle(rowWidth = 1600) {
		const handle = screen.getByRole("separator", {
			name: "Resize schema panel",
		});
		Object.defineProperty(handle.parentElement, "clientWidth", {
			value: rowWidth,
			configurable: true,
		});
		return handle;
	}

	function panelWidth() {
		const panel = document.querySelector("aside");
		return panel?.style.getPropertyValue("--schema-panel-width");
	}

	it("starts at the index width and reports it to assistive tech", () => {
		render(<EntityTypeGraphView ownerSlug="acme" />);

		expect(grabHandle().getAttribute("aria-valuenow")).toBe("288");
		expect(panelWidth()).toBe("288px");
	});

	it("widens the panel when the divider is nudged left", () => {
		render(<EntityTypeGraphView ownerSlug="acme" />);
		const handle = grabHandle();

		// Keyboard-reachable on purpose: the panel hosts the type editor, and a
		// pointer-only divider would put that behind a mouse.
		fireEvent.keyDown(handle, { key: "ArrowLeft" });

		expect(panelWidth()).toBe("304px");
	});

	it("narrows the panel when the divider is nudged right", () => {
		render(<EntityTypeGraphView ownerSlug="acme" />);
		const handle = grabHandle();

		fireEvent.keyDown(handle, { key: "ArrowRight" });

		expect(panelWidth()).toBe("272px");
	});

	it("refuses to squeeze the canvas away however far it is pushed", () => {
		render(<EntityTypeGraphView ownerSlug="acme" />);
		// A 900px row leaves 580px once the canvas keeps its 320px floor, which
		// bites well before the panel's own 720px ceiling.
		const handle = grabHandle(900);

		for (let i = 0; i < 40; i++) {
			fireEvent.keyDown(handle, { key: "ArrowLeft" });
		}

		expect(panelWidth()).toBe("580px");
	});

	it("holds the dragged width when the type editor opens", () => {
		// The editor default is wider than the index default. A drag that silently
		// reverted on open would read as the handle not working.
		render(<EntityTypeGraphView ownerSlug="acme" />);
		fireEvent.keyDown(grabHandle(), { key: "ArrowLeft" });

		fireEvent.click(screen.getByRole("button", { name: "Edit Person schema" }));

		expect(screen.getByTestId("type-editor")).toBeTruthy();
		expect(panelWidth()).toBe("304px");
	});

	it("hands sizing back to the mode default when reset", () => {
		render(<EntityTypeGraphView ownerSlug="acme" />);
		const handle = grabHandle();
		fireEvent.keyDown(handle, { key: "ArrowLeft" });
		expect(panelWidth()).toBe("304px");

		fireEvent.keyDown(handle, { key: "Home" });

		expect(panelWidth()).toBe("288px");
		// Back on the mode default, so the editor gets its own wider default again.
		fireEvent.click(screen.getByRole("button", { name: "Edit Person schema" }));
		expect(panelWidth()).toBe("440px");
	});

	it("opens the type editor wider than the index it replaces", () => {
		render(<EntityTypeGraphView ownerSlug="acme" />);

		fireEvent.click(screen.getByRole("button", { name: "Edit Person schema" }));

		expect(panelWidth()).toBe("440px");
	});

	it("resizes by pointer drag, not only by keyboard", () => {
		render(<EntityTypeGraphView ownerSlug="acme" />);
		const handle = grabHandle();
		// jsdom implements no pointer capture; the gesture only needs it so the
		// pointer may cross onto the canvas mid-drag.
		handle.setPointerCapture = vi.fn();
		handle.releasePointerCapture = vi.fn();

		fireEvent.pointerDown(handle, { button: 0, clientX: 1000, pointerId: 1 });
		// Leftward travel widens: 288 + 120.
		handle.dispatchEvent(
			new MouseEvent("pointermove", { clientX: 880, bubbles: true }),
		);

		expect(panelWidth()).toBe("408px");

		handle.dispatchEvent(
			new MouseEvent("pointerup", { clientX: 880, bubbles: true }),
		);
		expect(panelWidth()).toBe("408px");
	});

	it("ignores a non-primary button so no drag outlives its gesture", () => {
		// A right-drag starts a resize that the context menu's own pointerup never
		// ends, leaving the panel glued to the cursor.
		render(<EntityTypeGraphView ownerSlug="acme" />);
		const handle = grabHandle();
		handle.setPointerCapture = vi.fn();

		fireEvent.pointerDown(handle, { button: 2, clientX: 1000, pointerId: 1 });
		handle.dispatchEvent(
			new MouseEvent("pointermove", { clientX: 880, bubbles: true }),
		);

		expect(handle.setPointerCapture).not.toHaveBeenCalled();
		expect(panelWidth()).toBe("288px");
	});

	it("keeps the divider off a narrow viewport, where there is no split", () => {
		// Below `lg` the panel is either absent or full-bleed. The handle is in the
		// tree for assistive tech either way, so the breakpoint has to be the thing
		// that hides it.
		render(<EntityTypeGraphView ownerSlug="acme" />);

		expect(grabHandle().className).toContain("hidden");
		expect(grabHandle().className).toContain("lg:flex");
	});
});

