// React Flow owns the edge's `<g>`, so there is no prop to hang a focus
// handler on. It does stamp the edge id as `data-id`, and focus events reach
// the wrapper this component renders — so read the id off the way up rather
// than reaching into the library. Scoped to `.react-flow__edge` because the
// per-node browse and edit buttons are focusable too and sit inside their own
// `data-id` element.
const edgeIdFromFocus = (target: EventTarget | null): string | null => {
	if (!(target instanceof Element)) return null;
	return target.closest(".react-flow__edge")?.getAttribute("data-id") ?? null;
};

const handleCanvasFocus = useCallback((event: FocusEvent<HTMLDivElement>) => {
