// Standalone regression test for `Watcher`'s id decoding across gateway shapes.
//
// `manage_behaviors` stringifies the id; other gateway versions send it as a
// JSON number, and the field has been spelled both `behavior_id` and
// `watcher_id`. Decoding must accept all four combinations.
//
// The bug this pins: `decodeIfPresent(String.self, forKey:)` returns nil only
// for a missing or null key — on a JSON number it THROWS `typeMismatch`. Written
// as a String decode with an `else if` Int fallback, the fallback is
// unreachable and `try` fails the whole Behaviors response, not just the field.
//
//   swiftc apps/mac/Owletto/LobuClient.swift \
//          apps/mac/Tests/WatcherDecodingTests.swift -o /tmp/watcher-decoding-test \
//   && /tmp/watcher-decoding-test

import Foundation

// Minimal stubs for unrelated LobuClient references, matching AnyEncodableTests:
// compile the real decoder without pulling the SwiftUI app graph in.
struct McpWiring {
    let url: String
    let bearer: String
}

extension String {
    func trimmedTrailingSlash() -> String {
        var s = self
        while s.hasSuffix("/") { s.removeLast() }
        return s
    }
}

@main
struct WatcherDecodingTests {
    static var failures = 0

    static func check(_ cond: Bool, _ msg: String) {
        if !cond {
            failures += 1
            FileHandle.standardError.write(Data("FAIL: \(msg)\n".utf8))
        }
    }

    static func decode(_ json: String) -> Watcher? {
        try? JSONDecoder().decode(Watcher.self, from: Data(json.utf8))
    }

    static func main() throws {
        // A numeric id is the case that used to fail the whole response.
        let numericBehavior = decode(
            #"{"behavior_id":42,"name":"Daily digest","status":"active"}"#)
        check(numericBehavior?.id == 42, "numeric behavior_id must decode")

        let stringBehavior = decode(
            #"{"behavior_id":"42","name":"Daily digest","status":"active"}"#)
        check(stringBehavior?.id == 42, "stringified behavior_id must decode")

        // Same two shapes under the legacy key.
        let numericWatcher = decode(
            #"{"watcher_id":7,"name":"Legacy","status":"active"}"#)
        check(numericWatcher?.id == 7, "numeric watcher_id must decode")

        let stringWatcher = decode(
            #"{"watcher_id":"7","name":"Legacy","status":"active"}"#)
        check(stringWatcher?.id == 7, "stringified watcher_id must decode")

        // A response carrying neither key is still an error, not a silent zero.
        let missing = decode(#"{"name":"Nameless","status":"active"}"#)
        check(missing == nil, "a row with no id must fail to decode")

        // The surrounding fields must survive the id path.
        check(numericBehavior?.name == "Daily digest", "name must decode alongside a numeric id")
        check(numericBehavior?.status == "active", "status must decode alongside a numeric id")

        if failures == 0 {
            print("WatcherDecodingTests: all checks passed")
            exit(0)
        }
        FileHandle.standardError.write(Data("WatcherDecodingTests: \(failures) failure(s)\n".utf8))
        exit(1)
    }
}

