var finalizeNudge: String? = nil
// Safety cap so a buggy server cannot loop forever (server budget is usually 0–5).
let localMaxRounds = 8
for round in 0 ..< localMaxRounds {
    do {
        let result = try await executor.run(
            payload: job.payload,
            runId: job.run_id,
            timeout: timeout,
            mcp: client.mcpWiring,
            finalizeNudge: finalizeNudge
        )
        let report = try await client.completeBehaviorRun(
            workerId: workerId,
            runId: job.run_id,
            output: result.output,
            error: result.error,
            durationMs: result.durationMs,
            exitCode: result.exitCode.map { Int($0) },
            exitSignal: result.exitSignal,
            exitReason: result.exitReason
        )
        if report.shouldResume {
            finalizeNudge = report.nudge ?? report.error
                ?? "Prior attempt did not call completeWindow. Finalize via lobu CLI or MCP."
            NSLog(
                "[Owletto] Behavior run=%d resume attempt=%@ max=%@ round=%d",
                job.run_id,
                String(describing: report.attempt),
                String(describing: report.max_attempts),
                round + 1
            )
