/// A 2xx body from `complete-behavior`, read without inventing an outcome.
///
/// This decides durable delivery state, so it fails closed: anything not
/// recognised throws rather than being reported as a finished run. It used
/// to fall back to a synthesized `status: "completed"` for ANY body that
/// did not decode — so a truncated payload, an error envelope answered with
/// 200, or a proxy's HTML page all read as "the run finished", suppressing
/// the resume or reconciliation the server was asking for.
///
/// Throwing is the safe direction: `WatcherDispatcher` catches it and calls
/// `completeWithError`, which reports an explicit failure the server can
/// reconcile, instead of a success that never happened.
static func interpretCompleteBehaviorResponse(
    _ data: Data,
    decoder: JSONDecoder
) throws -> BehaviorExitReport {
    if let report = try? decoder.decode(BehaviorExitReport.self, from: data) {
        return report
    }
    // The one legitimate legacy shape: an older gateway answering 2xx with a
    // minimal object that carries no `status`. Recognised explicitly — and
    // still rejected if it actually signals failure.
    if let ack = try? decoder.decode(LegacyCompleteAck.self, from: data),
        ack.error == nil,
        ack.ok != false
    {
        return BehaviorExitReport(
            ok: true,
            status: "completed",
            reason_code: nil,
            attempt: nil,
            max_attempts: nil,
            nudge: nil,
            error: nil,
            window_id: nil,
            idempotent: nil
        )
    }
    throw WorkerClientError.decode(
        "complete-behavior returned an unrecognised 2xx body: "
            + (String(data: data.prefix(200), encoding: .utf8) ?? "<binary>")
    )
}

