///
/// A transport error (`URLError` and friends) never got an answer, so the
/// server may or may not have committed — re-sending is the only way to find
/// out, and the endpoints that matter are replayable. A 5xx/429 is the server
/// asking to be asked again. Any other HTTP status IS the answer: repeating the
/// request just repeats it.
///
/// Callers must not treat "not retriable" as "did not happen" — the request may
/// still have committed.
func isRetriableWorkerDeliveryFailure(_ error: Error) -> Bool {
    if case let WorkerClientError.http(_, code, _) = error {
        return code >= 500 || code == 429
    }
    // A decode failure means the server answered and we mangled the body;
    // re-sending would only mangle it again.
    if error is WorkerClientError { return false }
    return true
}

