// Standalone regression test for the device-held finalize loop in
// `WatcherDispatcher.dispatch` — the orchestration that decides durable
// delivery state for a Behavior run.
//
// The helpers around it were already covered (`CompleteBehaviorResponseTests`
// pins how one 2xx body is read); the loop that consumes those reports was not.
// That loop is where the costly mistakes live: re-spawning the CLI when the
// server only wanted the report re-sent, consuming a fresh finalize attempt on
// a retry, or answering an ambiguous delivery with a contradictory failure
// report that overwrites a decision the server already committed.
//
// Both seams needed already exist in production code, so nothing here is a
// test-only affordance: `LocalAgentExecutor` is a protocol, and
// `WorkerClient.init` takes an injectable `URLSession`. The stub below drives
// the real `WorkerClient` over a real `URLSession`, so the wire body — the
// `finalize_attempt` the server actually receives — is what gets asserted.
//
//   swiftc apps/mac/Owletto/WatcherDispatcher.swift \
//          apps/mac/Owletto/LocalAgentDetector.swift \
//          apps/mac/Owletto/LobuClient.swift \
//          apps/mac/Owletto/DeviceConnectorManifests.swift \
//          apps/mac/Tests/DispatcherResumeTests.swift -o /tmp/dispatcher-resume-test \
//   && /tmp/dispatcher-resume-test

import Foundation

// Minimal stub for an unrelated LobuClient reference, matching AnyEncodableTests.
extension String {
    func trimmedTrailingSlash() -> String {
        var s = self
        while s.hasSuffix("/") { s.removeLast() }
        return s
    }
}

// MARK: - HTTP stub

/// Scripted transport. Answers `complete-behavior` from a queue of canned
/// responses and records every request body; anything else (heartbeats) gets a
/// bare 200 so the dispatcher's liveness task doesn't interfere.
final class StubURLProtocol: URLProtocol {
    struct Reply {
        let status: Int
        let body: String
    }

    private static let lock = NSLock()
    private static var replies: [Reply] = []
    private static var recorded: [Data] = []

    static func script(_ replies: [Reply]) {
        lock.lock()
        defer { lock.unlock() }
        self.replies = replies
        recorded = []
    }

    /// Bodies posted to `complete-behavior`, in order.
    static var completions: [Data] {
        lock.lock()
        defer { lock.unlock() }
        return recorded
    }

    private static func next(recording body: Data) -> Reply {
        lock.lock()
        defer { lock.unlock() }
        recorded.append(body)
        // Past the end of the script the server keeps saying the same thing —
        // lets a test assert "and it stopped" without scripting the tail.
        guard !replies.isEmpty else { return Reply(status: 200, body: #"{"ok":true}"#) }
        return replies.count == 1 ? replies[0] : replies.removeFirst()
    }

    /// `URLSession` hands `URLProtocol` the body as a stream, not `httpBody`.
    private static func bodyData(_ request: URLRequest) -> Data {
        if let body = request.httpBody { return body }
        guard let stream = request.httpBodyStream else { return Data() }
        stream.open()
        defer { stream.close() }
        var data = Data()
        let size = 4096
        let buffer = UnsafeMutablePointer<UInt8>.allocate(capacity: size)
        defer { buffer.deallocate() }
        while stream.hasBytesAvailable {
            let read = stream.read(buffer, maxLength: size)
            if read <= 0 { break }
            data.append(buffer, count: read)
        }
        return data
    }

    override class func canInit(with request: URLRequest) -> Bool { true }
    override class func canonicalRequest(for request: URLRequest) -> URLRequest { request }

    override func startLoading() {
        let url = request.url!
        let reply: Reply
        if url.path.hasSuffix("/complete-behavior") {
            reply = Self.next(recording: Self.bodyData(request))
        } else {
            reply = Reply(status: 200, body: #"{"ok":true}"#)
        }
        let response = HTTPURLResponse(
            url: url, statusCode: reply.status, httpVersion: "HTTP/1.1",
            headerFields: ["Content-Type": "application/json"])!
        client?.urlProtocol(self, didReceive: response, cacheStoragePolicy: .notAllowed)
        client?.urlProtocol(self, didLoad: Data(reply.body.utf8))
        client?.urlProtocolDidFinishLoading(self)
    }

    override func stopLoading() {}
}

