/// Records what each spawn was asked to do. A spawn is the expensive,
/// user-visible side effect, so its count is the assertion that matters most.
final class RecordingExecutor: LocalAgentExecutor {
    let agentKind: AgentKind = .claudeCode
    var nudges: [String?] = []

    func run(
        payload _: WatcherPayload,
        runId _: Int,
        timeout _: TimeInterval,
        mcp _: McpWiring,
        finalizeNudge: String?
    ) async throws -> ExecutorResult {
        nudges.append(finalizeNudge)
        return ExecutorResult(
            output: "done", error: nil, exitCode: 0, exitSignal: nil,
            exitReason: "ok", durationMs: 1)
    }
}

