@MainActor
struct DispatcherResumeTests {
    static var failures = 0

    static func check(_ cond: Bool, _ msg: String) {
        if !cond {
            failures += 1
            FileHandle.standardError.write(Data("FAIL: \(msg)\n".utf8))
        }
    }

    static let jobJSON = """
        {"run_id":4242,"run_type":"behavior","organization_id":"org_test",
         "payload":{
           "watcher":{"id":"beh_1","name":"Test","slug":"test","agent_kind":"claude-code",
                      "notification_channel":null,"notification_priority":null,
                      "execution_config":{"timeout_seconds":5},
                      "prompt":"do a thing","extraction_schema":null},
           "event":{"trigger_event_id":null,"fired_at":"2026-07-30T00:00:00Z","payload":null},
           "context":{"device":{"worker_id":"wrk_1"},"user":{"user_id":"usr_1"}}}}
        """

    /// One dispatch against a scripted server. Returns the spawn nudges and the
    /// `finalize_attempt` carried by each posted report.
    static func dispatch(
        _ replies: [StubURLProtocol.Reply]
    ) async throws -> (nudges: [String?], attempts: [Int?]) {
        StubURLProtocol.script(replies)
        let config = URLSessionConfiguration.ephemeral
        config.protocolClasses = [StubURLProtocol.self]
        let client = WorkerClient(
            baseURL: "https://stub.invalid", accessToken: "t",
            session: URLSession(configuration: config))
        let executor = RecordingExecutor()
        let job = try JSONDecoder().decode(WatcherJob.self, from: Data(jobJSON.utf8))

        await WatcherDispatcher(executors: [executor])
            .dispatch(job: job, client: client, workerId: "wrk_1")

        let attempts = StubURLProtocol.completions.map { body -> Int? in
            let obj = try? JSONSerialization.jsonObject(with: body) as? [String: Any]
            return (obj?["finalize_attempt"] as? NSNumber)?.intValue
        }
        return (executor.nudges, attempts)
    }

    static func main() async throws {
        // 1. A granted resume re-spawns the CLI with the server's nudge, and the
        //    next report carries the server's attempt number — not a local
        //    increment, so the row stays the authority on the budget.
        let resumed = try await dispatch([
            .init(
                status: 200,
                body: #"{"ok":true,"status":"resume","attempt":1,"max_attempts":3,"nudge":"finalize it"}"#),
            .init(status: 200, body: #"{"ok":true,"status":"completed"}"#),
        ])
        check(resumed.nudges.count == 2, "a granted resume must spawn the CLI a second time")
        check(resumed.nudges.first ?? "x" == nil, "the first spawn carries no nudge")
        check(resumed.nudges.last ?? nil == "finalize it", "the resumed spawn must carry the server's nudge")
        check(resumed.attempts == [0, 1], "the resumed report must carry the server's attempt, got \(resumed.attempts)")

        // 2. A transient delivery failure re-sends the SAME report. It must not
        //    re-run the CLI (the turn already happened) and must not consume a
        //    fresh finalize attempt — the re-send exists to re-read one decision.
        let retried = try await dispatch([
            .init(status: 503, body: #"{"error":"upstream"}"#),
            .init(status: 200, body: #"{"ok":true,"status":"completed"}"#),
        ])
        check(retried.nudges.count == 1, "a delivery retry must not re-spawn the CLI")
        check(retried.attempts == [0, 0], "a re-sent report must replay the same finalize_attempt, got \(retried.attempts)")

        // 3. A non-retriable delivery failure IS the server's answer. The
        //    dispatcher must stay silent rather than posting a failure report
        //    that contradicts a decision the server may already have committed.
        let rejected = try await dispatch([.init(status: 400, body: #"{"error":"bad request"}"#)])
        check(rejected.nudges.count == 1, "a rejected delivery must not re-spawn the CLI")
        check(
            rejected.attempts.count == 1,
            "a non-retriable delivery must not be followed by a contradictory report, got \(rejected.attempts.count) posts")

        // 4. An unreadable 2xx body is a delivery failure, not a completion and
        //    not a resume. `interpretCompleteBehaviorResponse` throws, the throw
        //    is non-retriable (the server answered; re-sending re-mangles it), so
        //    the outcome is left unknown for the server's heartbeat-stale sweep.
        //    Nothing is fabricated in either direction.
        let garbled = try await dispatch([.init(status: 200, body: "<html>502</html>")])
        check(garbled.nudges.count == 1, "an unreadable body must not be read as a resume")
        check(
            garbled.attempts.count == 1,
            "an unreadable body must not trigger a second report, got \(garbled.attempts.count) posts")

        // 5. Termination: a server stuck on "resume" cannot spin the device
        //    forever. The local cap stops it and reports an explicit error, so
        //    the run row does not sit `running` until the coarse TTL.
        let capped = try await dispatch([
            .init(status: 200, body: #"{"ok":true,"status":"resume","nudge":"again"}"#)
        ])
        check(capped.nudges.count == 8, "the local safety cap must bound spawns at 8, got \(capped.nudges.count)")
        check(
            capped.attempts.count == 9,
            "the capped loop must post a final error report, got \(capped.attempts.count) posts")

        if failures == 0 {
            print("DispatcherResumeTests: all checks passed")
            exit(0)
        }
        FileHandle.standardError.write(Data("DispatcherResumeTests: \(failures) failure(s)\n".utf8))
        exit(1)
    }
}

